cd "$(dirname "$(readlink mjcf.xml)")"; python - <<'EOF'
import mujoco, numpy as np
m = mujoco.MjModel.from_xml_path("fixed_scene.xml")
print("nu",m.nu)
for i in range(m.nu):
    print("act",i,mujoco.mj_id2name(m,mujoco.mjtObj.mjOBJ_ACTUATOR,i),m.actuator_ctrlrange[i])
print("---sites---")
for i in range(m.nsite):
    print("site",mujoco.mj_id2name(m,mujoco.mjtObj.mjOBJ_SITE,i))
print("---target/base geoms/bodies---")
for i in range(m.nbody):
    n=mujoco.mj_id2name(m,mujoco.mjtObj.mjOBJ_BODY,i)
    if n and ('target' in n or 'base' in n): print("body",n)
for i in range(m.ngeom):
    n=mujoco.mj_id2name(m,mujoco.mjtObj.mjOBJ_GEOM,i)
    if n and ('target' in n or 'pad' in n or 'contact' in n): print("geom",n)
EOF
